local ServiceScope = require(script.Parent.ServiceScope)

-- 创建模拟的 ServiceProvider，增加更多跟踪功能
local function createMockServiceProvider()
	return {
		Parent = {
			Parent = nil,
			_scopes = {},
			GetService = function(self, serviceType)
				return "mock_" .. serviceType
			end,
			GetRequiredService = function(self, service)
				return "mock_" .. service
			end,
			Dispose = function(self)
				self.disposeCalled = true
			end,
		},
		_scopes = {},
		_createdObjectHistory = {},
		disposeCalled = false,
		DisposeCalled = false,
		GetService = function(self, serviceType)
			return "mock_" .. serviceType
		end,
		GetRequiredService = function(self, service)
			return "mock_" .. service
		end,
		Dispose = function(self)
			if self.DisposeCalled then
				return
			end
			self.DisposeCalled = true
			self.disposeCalled = true

			-- 添加对 _createdObjectHistory 中对象的销毁逻辑
			for _, item in ipairs(self._createdObjectHistory) do
				if not item.descriptor.ImplementationInstance then
					if type(item.object) == "table" and type(item.object.Dispose) == "function" then
						item.object:Dispose()
					end
				end
			end

			-- 销毁所有作用域
			for scope in pairs(self._scopes) do
				scope:Dispose()
			end
			self._scopes = {}
		end,
	}
end

return function()
	describe("ServiceScope", function()
		local mockProvider
		local scope

		beforeEach(function()
			mockProvider = createMockServiceProvider()
			scope = ServiceScope.new(mockProvider)
		end)

		it("should create new instance correctly", function()
			expect(scope).to.be.ok()
			expect(scope._serviceProvider).to.equal(mockProvider)
		end)

		it("should get service correctly", function()
			local result = scope:GetService("TestService")
			expect(result).to.equal("mock_TestService")
		end)

		it("should get service provider correctly", function()
			local provider = scope:GetServiceProvider()
			expect(provider).to.equal(mockProvider)
		end)

		describe("Dispose", function()
			it("should dispose provider and remove from parent scopes", function()
				local parentProvider = mockProvider.Parent
				parentProvider._scopes[scope] = true

				scope:Dispose()

				expect(mockProvider.disposeCalled).to.equal(true)
				expect(parentProvider._scopes[scope]).to.never.be.ok()
			end)

			it("should handle dispose when parent is nil", function()
				mockProvider.Parent = nil

				expect(function()
					scope:Dispose()
				end).never.to.throw()
				expect(mockProvider.disposeCalled).to.equal(true)
			end)

			it("should handle multiple dispose calls safely", function()
				local disposeCount = 0
				mockProvider.Dispose = function(self)
					disposeCount = disposeCount + 1
					self.disposeCalled = true
				end

				scope:Dispose()
				scope:Dispose()
				scope:Dispose()

				expect(disposeCount).to.equal(1)
			end)

			it("should handle parent scopes cleanup correctly", function()
				local parentProvider = mockProvider.Parent
				local scopeA = scope
				local scopeB = ServiceScope.new(mockProvider)

				parentProvider._scopes[scopeA] = true
				parentProvider._scopes[scopeB] = true

				scopeA:Dispose()

				expect(parentProvider._scopes[scopeA]).to.never.be.ok()
				expect(parentProvider._scopes[scopeB]).to.be.ok()
			end)

			it("should handle parent scope removal failure gracefully", function()
				local parentProvider = mockProvider.Parent
				parentProvider._scopes[scope] = true

				-- 模拟父级作用域删除失败
				parentProvider._scopes = setmetatable({}, {
					__newindex = function() end, -- 静默失败，而不是抛出错误
					__index = function(_, key)
						return parentProvider._scopes[key]
					end,
				})

				expect(function()
					scope:Dispose()
				end).never.to.throw()

				expect(mockProvider.disposeCalled).to.equal(true)
			end)

			it("should maintain correct state after dispose", function()
				local parentProvider = mockProvider.Parent
				parentProvider._scopes[scope] = true

				scope:Dispose()

				-- 验证服务获取行为
				expect(function()
					scope:GetService("TestService")
				end).never.to.throw()

				expect(function()
					scope:GetRequiredService("TestService")
				end).never.to.throw()
			end)
		end)

		describe("Service resolution after dispose", function()
			it("should handle GetService after dispose", function()
				scope:Dispose()
				local result = scope:GetService("TestService")
				expect(result).to.equal("mock_TestService")
			end)

			it("should handle GetRequiredService after dispose", function()
				scope:Dispose()
				local result = scope:GetRequiredService("TestService")
				expect(result).to.equal("mock_TestService")
			end)
		end)

		it("should not cause multiple dispose calls when provider is being disposed", function()
			local disposeCount = 0
			local mockService = {
				Dispose = function(self)
					disposeCount = disposeCount + 1
				end,
			}

			-- 创建一个作用域并添加到 provider 的 scopes 中
			local testScope = ServiceScope.new(mockProvider)
			mockProvider._scopes[testScope] = true

			-- 模拟服务提供者中有一个需要销毁的服务
			mockProvider._createdObjectHistory = {
				{
					descriptor = { ImplementationInstance = false },
					object = mockService,
				},
			}

			-- 通过 Provider 触发销毁
			mockProvider:Dispose()

			-- 验证服务的 Dispose 只被调用一次
			expect(disposeCount).to.equal(1)
		end)
	end)
end
